Add-Type -AssemblyName System.Drawing
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$W=1080; $H=1350
$navy=[Drawing.ColorTranslator]::FromHtml('#0D326F'); $ink=[Drawing.ColorTranslator]::FromHtml('#17233D'); $muted=[Drawing.ColorTranslator]::FromHtml('#596173'); $paper=[Drawing.ColorTranslator]::FromHtml('#FBFAF7'); $gold=[Drawing.ColorTranslator]::FromHtml('#9A7423'); $teal=[Drawing.ColorTranslator]::FromHtml('#167C76'); $line=[Drawing.ColorTranslator]::FromHtml('#E3DDCF')
function Font($size,$bold=$false){New-Object Drawing.Font('Malgun Gothic',$size,($(if($bold){[Drawing.FontStyle]::Bold}else{[Drawing.FontStyle]::Regular})),[Drawing.GraphicsUnit]::Pixel)}
function RoundRect($g,$brush,$pen,$x,$y,$w,$h,$r){$p=New-Object Drawing.Drawing2D.GraphicsPath;$p.AddArc($x,$y,$r,$r,180,90);$p.AddArc($x+$w-$r,$y,$r,$r,270,90);$p.AddArc($x+$w-$r,$y+$h-$r,$r,$r,0,90);$p.AddArc($x,$y+$h-$r,$r,$r,90,90);$p.CloseFigure();if($brush){$g.FillPath($brush,$p)};if($pen){$g.DrawPath($pen,$p)};$p.Dispose()}
function Text($g,$s,$font,$color,$x,$y,$w,$h){$b=New-Object Drawing.SolidBrush($color);$f=New-Object Drawing.StringFormat;$f.Trimming=[Drawing.StringTrimming]::Word;$g.DrawString($s,$font,$b,[Drawing.RectangleF]::new($x,$y,$w,$h),$f);$b.Dispose();$f.Dispose()}
function Base($n,$label){$bmp=New-Object Drawing.Bitmap($W,$H);$g=[Drawing.Graphics]::FromImage($bmp);$g.SmoothingMode='HighQuality';$g.TextRenderingHint='ClearTypeGridFit';$g.Clear($paper);Text $g '보험워크 · 실손 재가입 안내' (Font 24 $true) $gold 72 60 700 45;RoundRect $g (New-Object Drawing.SolidBrush($navy)) $null 944 52 64 64 22;Text $g $n (Font 28 $true) ([Drawing.Color]::White) 960 64 50 45;@($bmp,$g)}
function Panel($g,$x,$y,$w,$h){RoundRect $g (New-Object Drawing.SolidBrush([Drawing.Color]::White)) (New-Object Drawing.Pen($line,2)) $x $y $w $h 26}
function Bottom($g,$s){RoundRect $g (New-Object Drawing.SolidBrush($navy)) $null 72 1190 936 92 24;Text $g $s (Font 24 $true) ([Drawing.Color]::White) 104 1214 872 55}

# 1
$a=Base '1' ''; $bmp=$a[0];$g=$a[1];Text $g '먼저 내 계약부터 확인하세요' (Font 28 $true) $teal 72 170 700 45;Text $g "나는 실손보험`n재가입 대상일까요?" (Font 65 $true) $ink 72 220 850 180;Text $g "가입 시기만으로 단정하지 말고,`n보험증권과 약관의 재가입 조항을 확인해야 합니다." (Font 28) $muted 72 420 850 110;Panel $g 72 560 585 390;Text $g '확인할 4가지' (Font 34 $true) $ink 112 600 400 55;Text $g "✓ 최초 가입일       ✓ 현재 상품명`n✓ 재가입 조항       ✓ 재가입 예정일" (Font 26 $true) $teal 112 675 510 110;Text $g "특히 2013년 3월 이전 계약 중에는`n재가입 조건이 없는 계약도 있습니다." (Font 26) $ink 112 815 500 100;$img=[Drawing.Image]::FromFile((Join-Path $root 'renewal-advisor.png'));$g.DrawImage($img,520,660,610,500);$img.Dispose();Bottom $g '한 줄 정리  |  세대보다 내 약관의 재가입 조항을 먼저 확인하세요.';$bmp.Save((Join-Path $root 'customer-card-01.png'),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose()

# 2
$a=Base '2' ''; $bmp=$a[0];$g=$a[1];Text $g '보험사 안내를 받았다면' (Font 28 $true) $teal 72 170 700 45;Text $g "이 순서대로`n확인하세요" (Font 65 $true) $ink 72 220 850 180;Panel $g 72 440 936 690;$steps=@(@('1','안내문 도착 여부 확인','문자·우편·앱 알림을 확인하고 연락처를 최신화하세요.'),@('2','바뀌는 조건 비교','보장 범위·자기부담금·보험료·계약기간을 확인하세요.'),@('3','기한 안에 의사 표시','안내문에 적힌 회신 방법과 처리 기한에 따라 응답하세요.'),@('4','완료 여부 다시 확인','처리 결과와 새 보험증권을 보험사에서 확인하세요.'));$y=485;foreach($s in $steps){RoundRect $g (New-Object Drawing.SolidBrush($navy)) $null 112 $y 62 62 20;Text $g $s[0] (Font 27 $true) ([Drawing.Color]::White) 131 ($y+10) 40 40;Text $g $s[1] (Font 30 $true) $ink 205 ($y-3) 720 45;Text $g $s[2] (Font 24) $muted 205 ($y+42) 730 65;$y+=158};Bottom $g '중요  |  보험금 청구 중이어도 재가입 완료 여부는 별도로 확인하세요.';$bmp.Save((Join-Path $root 'customer-card-02.png'),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose()

# 3
$a=Base '3' ''; $bmp=$a[0];$g=$a[1];Text $g '응답을 놓쳤거나 연락을 못 받았다면' (Font 28 $true) $teal 72 170 850 45;Text $g "자동연장일까요?`n보장이 끝날까요?" (Font 62 $true) $ink 72 220 900 180;Text $g "정답은 하나가 아닙니다. 가입한 상품과 약관에 따라`n처리 방식이 달라질 수 있습니다." (Font 27) $muted 72 415 900 100;$items=@(@('자동연장 여부','모든 실손 계약에 같은 기준이 적용되지는 않습니다.'),@('보장 종료 여부','세대명만 보고 보장이 소멸한다고 단정하지 마세요.'),@('철회·환급 가능 여부','가능 기간과 환급 범위는 안내문·약관을 확인하세요.'),@('연락처 변경','보험사와 담당 설계사에게 최신 정보를 등록하세요.'));$y=555;foreach($it in $items){Panel $g 72 $y 936 120;Text $g $it[0] (Font 27 $true) $navy 105 ($y+20) 310 45;Text $g $it[1] (Font 23) $muted 405 ($y+20) 560 70;$y+=140};RoundRect $g (New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml('#FFF3D7'))) $null 72 1115 936 58 18;Text $g '주의  |  자동연장·계약 종료·환급 기준을 모든 고객에게 똑같이 안내하지 마세요.' (Font 21 $true) ([Drawing.ColorTranslator]::FromHtml('#664B10')) 98 1129 885 35;Bottom $g '지금 할 일  |  보험증권과 안내문을 준비해 내 계약 기준으로 확인하세요.';$bmp.Save((Join-Path $root 'customer-card-03.png'),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose()

