$a=Base '✓' ''; $bmp=$a[0];$g=$a[1];Text $g '고객에게 보내기 전 내부 확인' (Font 28 $true) $teal 72 155 800 45;Text $g "실손 재가입`n판정 체크리스트" (Font 58 $true) $ink 72 205 900 160;Panel $g 72 390 936 545;$rows=@('계약 식별   | 보험사·상품명·최초 가입일   | 보험증권','재가입 조항 | 조항 유무·주기·예정일       | 해당 약관','변경 조건   | 보장·자기부담금·보험료      | 공식 안내문','미응답 처리 | 자동연장·종료 등 실제 기준  | 약관/보험사','철회·환급   | 가능 기간·금액 산정 방식    | 약관/보험사','안내 기록   | 문자·통화·상담 일시         | 상담 기록');$y=425;foreach($r in $rows){Text $g $r (Font 22) $ink 105 $y 850 50;$y+=78};RoundRect $g (New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml('#FFF3D7'))) $null 72 965 936 92 20;Text $g "2026-08-27 기준  |  5세대 실손보험 공식 출시일은 2026년 5월 6일입니다." (Font 23 $true) ([Drawing.ColorTranslator]::FromHtml('#664B10')) 102 987 870 55;Panel $g 72 1080 936 190;Text $g '고객 안내 문구' (Font 27 $true) $navy 105 1102 800 42;Text $g "실손보험 재가입 기준은 가입 시기와 상품 약관에 따라 다릅니다.`n내 계약의 정확한 재가입일과 변경 내용을 미리 확인하세요." (Font 22) $ink 105 1150 845 72;Text $g '출처: 금융위원회 5세대 실손의료보험 출시(2026.05.06)' (Font 17) $muted 105 1235 800 28;$bmp.Save((Join-Path $root 'advisor-checklist.png'),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose()
